-- Hastkatha: header image per blog post, generated by the daily-blog cron
-- and stored in its own public bucket. One image per post (not per
-- translation) — the same image is shown regardless of reading language.
-- Run this in Supabase: Dashboard -> SQL Editor -> New query -> paste -> Run.

alter table blogs add column if not exists image_url text;

insert into storage.buckets (id, name, public)
values ('blog-images', 'blog-images', true)
on conflict (id) do nothing;

-- Posts are written server-side only (the daily-blog cron, using the
-- service-role key, which bypasses RLS entirely) — there is no per-user
-- owner to check, so the only policy needed here is public read access.
create policy "read blog images" on storage.objects for select using (bucket_id = 'blog-images');
